 using ModelContextProtocol.Protocol;
 using ModelContextProtocol.Server;
 using System.Text.Json;

 namespace McpHttpServer;

 [McpServerResourceType]
 public class ConfigResource
 {
     private static readonly Dictionary<string, object> _config = new()
     {
         ["environment"] = "production",
         ["version"] = "1.0.0",
         ["features"] = new Dictionary<string, bool>
         {
             ["darkMode"] = true,
             ["notifications"] = true,
             ["betaFeatures"] = false
         }
     };

     [McpServerResource(UriTemplate = "config://app/settings", Name = "AppSettings", MimeType = "application/json")]
     public static ReadResourceResult GetSettings()
     {
         var json = JsonSerializer.Serialize(_config, new JsonSerializerOptions { WriteIndented = true });

         return new ReadResourceResult
         {
             Contents =
             [
                 new TextResourceContents
                 {
                     Uri = "config://app/settings",
                     MimeType = "application/json",
                     Text = json
                 }
             ]
         };
     }
 }

